real_t algorithm_histogram(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        // Zero-initialize x[0..255] using RVV
        for (Index_type i = 0; i < 256; ) {
            size_t vl = __riscv_vsetvl_e32m1(256 - i);
            vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
            __riscv_vse32_v_f32m1(&x[i], vzero, vl);
            i += vl;
        }

        // Histogram accumulation using indexed loads/stores
        // Process LEN_1D elements, but indexed scatter is not directly available
        // as a single instruction in RVV 1.0. We use a manual vectorized approach:
        // Load indices, load x values, add 1.0, store back.
        Index_type i = 0;
        for (; i + 4 <= LEN_1D; i += 4) {
            // Load 4 indices
            Index_type idx0 = idx_list[i];
            Index_type idx1 = idx_list[i+1];
            Index_type idx2 = idx_list[i+2];
            Index_type idx3 = idx_list[i+3];
