            real_t v1 = x[idx1];
            real_t v2 = x[idx2];
            real_t v3 = x[idx3];
            // Increment
            v0 += 1.0f;
            v1 += 1.0f;
            v2 += 1.0f;
            v3 += 1.0f;
            // Store back
            x[idx0] = v0;
            x[idx1] = v1;
            x[idx2] = v2;
            x[idx3] = v3;
        }
        // Handle remaining elements
        for (; i < LEN_1D; ++i) {
            x[idx_list[i]] += 1.0f;
        }

        dummy(x, NULL, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
