real_t algorithm_scan(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        real_t scan_var = 0.0;
        Index_type i = 0;

#if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t vec_x, vec_y;
        vfloat32m1_t vec_zero = __riscv_vfmv_v_f_f32m1(0.0f, 1);

        for (; i + 8 <= LEN_1D; i += 8) {
            vl = __riscv_vsetvl_e32m1(8);
            vec_x = __riscv_vle32_v_f32m1(&x[i], vl);

            // Exclusive scan: compute cumulative sum, then shift
            // Prefix sum (inclusive scan) using vector operations
            vfloat32m1_t vec_sum = vec_x;
            // stride 1 shift and add
            vfloat32m1_t vec_shift1 = __riscv_vslidedown_vx_f32m1(vec_sum, 1, vl);
            vec_sum = __riscv_vfadd_vv_f32m1(vec_sum, vec_shift1, vl);
            // stride 2 shift and add
            vfloat32m1_t vec_shift2 = __riscv_vslidedown_vx_f32m1(vec_sum, 2, vl);
            vec_sum = __riscv_vfadd_vv_f32m1(vec_sum, vec_shift2, vl);
            // stride 4 shift and add
            vfloat32m1_t vec_shift4 = __riscv_vslidedown_vx_f32m1(vec_sum, 4, vl);
            vec_sum = __riscv_vfadd_vv_f32m1(vec_sum, vec_shift4, vl);

            // Now vec_sum holds inclusive scan of vec_x
            // For exclusive scan, shift right by 1 and insert scan_var at position 0
            vfloat32m1_t vec_excl = __riscv_vslidedown_vx_f32m1(vec_sum, 1, vl);
            vec_excl = __riscv_vfadd_vf_f32m1(vec_excl, scan_var, vl);
            // First element should be scan_var
            vec_excl = __riscv_vfslide1up_vf_f32m1(vec_excl, scan_var, vl);

            __riscv_vse32_v_f32m1(&y[i], vec_excl, vl);

            // Update scan_var with the total sum of this block
            // Extract last element of vec_sum
            real_t block_sum;
            vfloat32m1_t vec_last = __riscv_vslidedown_vx_f32m1(vec_sum, vl - 1, vl);
            __riscv_vse32_v_f32m1(&block_sum, vec_last, 1);
            scan_var += block_sum;
        }

        // Handle remaining elements with scalar code
        for (; i < LEN_1D; ++i) {
            y[i] = scan_var;
            scan_var += x[i];
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            y[i] = scan_var;
            scan_var += x[i];
        }
#endif

        dummy(x, y, NULL, NULL, NULL, scan_var);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

