            vfloat32m1_t vfy3 = __riscv_vle32_v_f32m1(&apps_fy3[i], vl);
            vfloat32m1_t vfy4 = __riscv_vle32_v_f32m1(&apps_fy4[i], vl);

            vfloat32m1_t vhalf = __riscv_vfmv_v_f_f32m1(half, vl);
            vfloat32m1_t vptiny = __riscv_vfmv_v_f_f32m1(ptiny, vl);

            vfloat32m1_t vx1_plus_x2 = __riscv_vfadd_vv_f32m1(vx1, vx2, vl);
            vfloat32m1_t vx3_plus_x4 = __riscv_vfadd_vv_f32m1(vx3, vx4, vl);
            vfloat32m1_t vxi = __riscv_vfmul_vv_f32m1(vhalf, __riscv_vfsub_vv_f32m1(vx1_plus_x2, vx3_plus_x4, vl), vl);

            vfloat32m1_t vx2_plus_x3 = __riscv_vfadd_vv_f32m1(vx2, vx3, vl);
            vfloat32m1_t vx4_plus_x1 = __riscv_vfadd_vv_f32m1(vx4, vx1, vl);
            vfloat32m1_t vxj = __riscv_vfmul_vv_f32m1(vhalf, __riscv_vfsub_vv_f32m1(vx2_plus_x3, vx4_plus_x1, vl), vl);

            vfloat32m1_t vy1_plus_y2 = __riscv_vfadd_vv_f32m1(vy1, vy2, vl);
            vfloat32m1_t vy3_plus_y4 = __riscv_vfadd_vv_f32m1(vy3, vy4, vl);
            vfloat32m1_t vyi = __riscv_vfmul_vv_f32m1(vhalf, __riscv_vfsub_vv_f32m1(vy1_plus_y2, vy3_plus_y4, vl), vl);

            vfloat32m1_t vy2_plus_y3 = __riscv_vfadd_vv_f32m1(vy2, vy3, vl);
            vfloat32m1_t vy4_plus_y1 = __riscv_vfadd_vv_f32m1(vy4, vy1, vl);
            vfloat32m1_t vyj = __riscv_vfmul_vv_f32m1(vhalf, __riscv_vfsub_vv_f32m1(vy2_plus_y3, vy4_plus_y1, vl), vl);

            vfloat32m1_t vfx1_plus_fx2 = __riscv_vfadd_vv_f32m1(vfx1, vfx2, vl);
            vfloat32m1_t vfx3_plus_fx4 = __riscv_vfadd_vv_f32m1(vfx3, vfx4, vl);
            vfloat32m1_t vfxi = __riscv_vfmul_vv_f32m1(vhalf, __riscv_vfsub_vv_f32m1(vfx1_plus_fx2, vfx3_plus_fx4, vl), vl);

            vfloat32m1_t vfx2_plus_fx3 = __riscv_vfadd_vv_f32m1(vfx2, vfx3, vl);
            vfloat32m1_t vfx4_plus_fx1 = __riscv_vfadd_vv_f32m1(vfx4, vfx1, vl);
            vfloat32m1_t vfxj = __riscv_vfmul_vv_f32m1(vhalf, __riscv_vfsub_vv_f32m1(vfx2_plus_fx3, vfx4_plus_fx1, vl), vl);

            vfloat32m1_t vfy1_plus_fy2 = __riscv_vfadd_vv_f32m1(vfy1, vfy2, vl);
            vfloat32m1_t vfy3_plus_fy4 = __riscv_vfadd_vv_f32m1(vfy3, vfy4, vl);
            vfloat32m1_t vfyi = __riscv_vfmul_vv_f32m1(vhalf, __riscv_vfsub_vv_f32m1(vfy1_plus_fy2, vfy3_plus_fy4, vl), vl);

            vfloat32m1_t vfy2_plus_fy3 = __riscv_vfadd_vv_f32m1(vfy2, vfy3, vl);
            vfloat32m1_t vfy4_plus_fy1 = __riscv_vfadd_vv_f32m1(vfy4, vfy1, vl);
            vfloat32m1_t vfyj = __riscv_vfmul_vv_f32m1(vhalf, __riscv_vfsub_vv_f32m1(vfy2_plus_fy3, vfy4_plus_fy1, vl), vl);

            vfloat32m1_t vxi_mul_vyj = __riscv_vfmul_vv_f32m1(vxi, vyj, vl);
            vfloat32m1_t vxj_mul_vyi = __riscv_vfmul_vv_f32m1(vxj, vyi, vl);
            vfloat32m1_t vdenom = __riscv_vfadd_vv_f32m1(__riscv_vfsub_vv_f32m1(vxi_mul_vyj, vxj_mul_vyi, vl), vptiny, vl);
            vfloat32m1_t vrarea = __riscv_vfrdiv_vf_f32m1(vdenom, 1.0f, vl);

            vfloat32m1_t vfxi_mul_vyj = __riscv_vfmul_vv_f32m1(vfxi, vyj, vl);
            vfloat32m1_t vfxj_mul_vyi = __riscv_vfmul_vv_f32m1(vfxj, vyi, vl);
            vfloat32m1_t vdfxdx = __riscv_vfmul_vv_f32m1(vrarea, __riscv_vfsub_vv_f32m1(vfxi_mul_vyj, vfxj_mul_vyi, vl), vl);

            vfloat32m1_t vfyj_mul_vxi = __riscv_vfmul_vv_f32m1(vfyj, vxi, vl);
            vfloat32m1_t vfyi_mul_vxj = __riscv_vfmul_vv_f32m1(vfyi, vxj, vl);
            vfloat32m1_t vdfydy = __riscv_vfmul_vv_f32m1(vrarea, __riscv_vfsub_vv_f32m1(vfyj_mul_vxi, vfyi_mul_vxj, vl), vl);

            vfloat32m1_t vfy_sum = __riscv_vfadd_vv_f32m1(__riscv_vfadd_vv_f32m1(vfy1, vfy2, vl), __riscv_vfadd_vv_f32m1(vfy3, vfy4, vl), vl);
            vfloat32m1_t vy_sum  = __riscv_vfadd_vv_f32m1(__riscv_vfadd_vv_f32m1(vy1, vy2, vl), __riscv_vfadd_vv_f32m1(vy3, vy4, vl), vl);
            vfloat32m1_t vaffine = __riscv_vfdiv_vv_f32m1(vfy_sum, vy_sum, vl);

            vfloat32m1_t vresult = __riscv_vfadd_vv_f32m1(__riscv_vfadd_vv_f32m1(vdfxdx, vdfydy, vl), vaffine, vl);
            __riscv_vse32_v_f32m1(&apps_div[i], vresult, vl);
        }
#else
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t xi  = half * ( apps_x1[i]  + apps_x2[i]  - apps_x3[i]  - apps_x4[i]  );
            real_t xj  = half * ( apps_x2[i]  + apps_x3[i]  - apps_x4[i]  - apps_x1[i]  );
            real_t yi  = half * ( apps_y1[i]  + apps_y2[i]  - apps_y3[i]  - apps_y4[i]  );
            real_t yj  = half * ( apps_y2[i]  + apps_y3[i]  - apps_y4[i]  - apps_y1[i]  );
            real_t fxi = half * ( apps_fx1[i] + apps_fx2[i] - apps_fx3[i] - apps_fx4[i] );
            real_t fxj = half * ( apps_fx2[i] + apps_fx3[i] - apps_fx4[i] - apps_fx1[i] );
            real_t fyi = half * ( apps_fy1[i] + apps_fy2[i] - apps_fy3[i] - apps_fy4[i] );
            real_t fyj = half * ( apps_fy2[i] + apps_fy3[i] - apps_fy4[i] - apps_fy1[i] );
            real_t rarea = 1.0f / ( xi * yj - xj * yi + ptiny );
            real_t dfxdx  = rarea * ( fxi * yj - fxj * yi );
            real_t dfydy  = rarea * ( fyj * xi - fyi * xj );
            real_t affine = ( apps_fy1[i] + apps_fy2[i] + apps_fy3[i] + apps_fy4[i] ) /
                            ( apps_y1[i]  + apps_y2[i]  + apps_y3[i]  + apps_y4[i]  );
            apps_div[i] = dfxdx + dfydy + affine;
        }
#endif
        dummy(apps_div, NULL, NULL, NULL, NULL, ptiny);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

