real_t apps_energy(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t rho0 = 1.0f, e_cut = 1.0e-7f, emin = -1.0e15f;
    const real_t zero = 0.0f;
    const real_t half = 0.5f;
    const real_t three = 3.0f;
    const real_t four = 4.0f;
    const real_t ssc_thresh = 1.111111e-36f;
    const real_t ssc_min = 3.333333e-18f;

    for (int nl = 0; nl < iterations / 8 + 1; nl++) {
        #if defined(__riscv_vector)
        size_t vl;
        for (Index_type i = 0; i < APPS_N1D; i += vl) {
            vl = __riscv_vsetvl_e32m1(APPS_N1D - i);
            vfloat32m1_t vdelvc = __riscv_vle32_v_f32m1(&apps_delvc[i], vl);
            vfloat32m1_t vp_old = __riscv_vle32_v_f32m1(&apps_p_old[i], vl);
            vfloat32m1_t vq_old = __riscv_vle32_v_f32m1(&apps_q_old[i], vl);
            vfloat32m1_t vwork = __riscv_vle32_v_f32m1(&apps_work[i], vl);
            vfloat32m1_t ve_old = __riscv_vle32_v_f32m1(&apps_e_old[i], vl);

            vfloat32m1_t vsum = __riscv_vfadd_vv_f32m1(vp_old, vq_old, vl);
            vfloat32m1_t vterm = __riscv_vfmul_vf_f32m1(vsum, half, vl);
            vterm = __riscv_vfmul_vv_f32m1(vterm, vdelvc, vl);
            vfloat32m1_t vwork_half = __riscv_vfmul_vf_f32m1(vwork, half, vl);
            vfloat32m1_t ve_new = __riscv_vfsub_vv_f32m1(ve_old, vterm, vl);
            ve_new = __riscv_vfadd_vv_f32m1(ve_new, vwork_half, vl);

            __riscv_vse32_v_f32m1(&apps_e_new[i], ve_new, vl);
        }

        for (Index_type i = 0; i < APPS_N1D; i += vl) {
            vl = __riscv_vsetvl_e32m1(APPS_N1D - i);
            vfloat32m1_t vdelvc = __riscv_vle32_v_f32m1(&apps_delvc[i], vl);
            vbool32_t mask = __riscv_vmfgt_vf_f32m1_b32(vdelvc, zero, vl);

            vfloat32m1_t vcomp = __riscv_vle32_v_f32m1(&apps_compHalfStep[i], vl);
            vfloat32m1_t vpbvc = __riscv_vle32_v_f32m1(&apps_pbvc[i], vl);
            vfloat32m1_t ve_new = __riscv_vle32_v_f32m1(&apps_e_new[i], vl);
            vfloat32m1_t vbvc = __riscv_vle32_v_f32m1(&apps_bvc[i], vl);
            vfloat32m1_t vpHalf = __riscv_vle32_v_f32m1(&apps_pHalfStep[i], vl);
            vfloat32m1_t vql_old = __riscv_vle32_v_f32m1(&apps_ql_old[i], vl);
            vfloat32m1_t vqq_old = __riscv_vle32_v_f32m1(&apps_qq_old[i], vl);

            vfloat32m1_t vone = __riscv_vfmv_v_f_f32m1(1.0f, vl);
            vfloat32m1_t vdenom = __riscv_vfadd_vf_f32m1(vcomp, 1.0f, vl);
            vfloat32m1_t vhalf_val = __riscv_vfdiv_vv_f32m1(vone, vdenom, vl);

            vfloat32m1_t vterm1 = __riscv_vfmul_vv_f32m1(vpbvc, ve_new, vl);
            vfloat32m1_t vhalf_sq = __riscv_vfmul_vv_f32m1(vhalf_val, vhalf_val, vl);
            vfloat32m1_t vterm2 = __riscv_vfmul_vv_f32m1(vhalf_sq, vbvc, vl);
            vterm2 = __riscv_vfmul_vv_f32m1(vterm2, vpHalf, vl);
            vfloat32m1_t vssc = __riscv_vfadd_vv_f32m1(vterm1, vterm2, vl);
