real_t basic_trap_int(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t x0 = 0.0, h = 1.0 / (real_t)LEN_1D;
    real_t yp = 1.0, ypoint = 1.0;
    real_t acc = 0.0;
    real_t yp_diff = ypoint - yp;
    real_t yp_diff_sq = yp_diff * yp_diff;

    for (int nl = 0; nl < iterations; nl++) {
        real_t sumx = 0.0;
        #if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t vec_sum = __riscv_vfmv_s_f_f32m1(0.0f, 1);
        vfloat32m1_t vec_h = __riscv_vfmv_v_f_f32m1(h, 1);
        vfloat32m1_t vec_yp_diff_sq = __riscv_vfmv_v_f_f32m1(yp_diff_sq, 1);
        vfloat32m1_t vec_one = __riscv_vfmv_v_f_f32m1(1.0f, 1);

        for (Index_type i = 0; i < LEN_1D; i += vl) {
            vl = __riscv_vsetvl_e32m1(LEN_1D - i);
            vuint32m1_t vec_i_uint = __riscv_vmv_v_x_u32m1(i, vl);
            vuint32m1_t vec_step = __riscv_vid_v_u32m1(vl);
            vec_i_uint = __riscv_vadd_vv_u32m1(vec_i_uint, vec_step, vl);
            vfloat32m1_t vec_i = __riscv_vfcvt_f_xu_v_f32m1(vec_i_uint, vl);
            vfloat32m1_t vec_xv = __riscv_vfmacc_vf_f32m1(__riscv_vfmv_v_f_f32m1(x0, vl), h, vec_i, vl);
            vfloat32m1_t vec_diff = __riscv_vfsub_vf_f32m1(vec_xv, 0.5f, vl);
            vfloat32m1_t vec_diff_sq = __riscv_vfmul_vv_f32m1(vec_diff, vec_diff, vl);
            vfloat32m1_t vec_denom = __riscv_vfadd_vv_f32m1(vec_diff_sq, vec_yp_diff_sq, vl);
            vfloat32m1_t vec_denom_plus1 = __riscv_vfadd_vv_f32m1(vec_denom, vec_one, vl);
            vfloat32m1_t vec_rsqrt = __riscv_vfrsqrt7_v_f32m1(vec_denom_plus1, vl);
            vec_sum = __riscv_vfredusum_vs_f32m1_f32m1(vec_rsqrt, vec_sum, vl);
        }
        sumx = __riscv_vfmv_f_s_f32m1_f32(vec_sum);
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t xv = x0 + i*h;
            real_t denom = (xv - 0.5)*(xv - 0.5) + yp_diff_sq;
            sumx += 1.0f / sqrtf(denom + 1.0f);
        }
        #endif
        acc += sumx;
        dummy(NULL, NULL, NULL, NULL, NULL, sumx);
    }
    x[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

