            // px[i + offset*9] = cr
            __riscv_vse64_v_f64m1((double *)&px[i + offset * 9], vcr, vl);

            // Load px[i + offset*10]
            vpx = __riscv_vle64_v_f64m1((const double *)&px[i + offset * 10], vl);
            // br = ar - px[i + offset*10]
