real_t lcals_eos(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t r = 0.5, t = 0.25, q = 0.125;
    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t vr, vt, vq;
        vr = __riscv_vfmv_v_f_f32m1(r, 1);
        vt = __riscv_vfmv_v_f_f32m1(t, 1);
        vq = __riscv_vfmv_v_f_f32m1(q, 1);

        for (Index_type i = 0; i < LEN_1D - 6; ) {
            vl = __riscv_vsetvl_e32m1(LEN_1D - 6 - i);

            vfloat32m1_t vu_i   = __riscv_vle32_v_f32m1(&u[i], vl);
            vfloat32m1_t vz_i   = __riscv_vle32_v_f32m1(&z[i], vl);
            vfloat32m1_t vy_i   = __riscv_vle32_v_f32m1(&y[i], vl);
            vfloat32m1_t vu_i1  = __riscv_vle32_v_f32m1(&u[i+1], vl);
            vfloat32m1_t vu_i2  = __riscv_vle32_v_f32m1(&u[i+2], vl);
            vfloat32m1_t vu_i3  = __riscv_vle32_v_f32m1(&u[i+3], vl);
            vfloat32m1_t vu_i4  = __riscv_vle32_v_f32m1(&u[i+4], vl);
            vfloat32m1_t vu_i5  = __riscv_vle32_v_f32m1(&u[i+5], vl);
            vfloat32m1_t vu_i6  = __riscv_vle32_v_f32m1(&u[i+6], vl);

            // inner: u[i+5] + q*u[i+4]
            vfloat32m1_t vtmp1 = __riscv_vfmacc_vf_f32m1(vu_i5, q, vu_i4, vl);
            // inner: u[i+6] + q*( u[i+5] + q*u[i+4] )
            vfloat32m1_t vtmp2 = __riscv_vfmacc_vf_f32m1(vu_i6, q, vtmp1, vl);
            // inner: t*( u[i+6] + q*( u[i+5] + q*u[i+4] ) )
            vfloat32m1_t vtmp3 = __riscv_vfmul_vf_f32m1(vtmp2, t, vl);

            // inner: u[i+2] + r*u[i+1]
            vfloat32m1_t vtmp4 = __riscv_vfmacc_vf_f32m1(vu_i2, r, vu_i1, vl);
            // inner: u[i+3] + r*( u[i+2] + r*u[i+1] )
            vfloat32m1_t vtmp5 = __riscv_vfmacc_vf_f32m1(vu_i3, r, vtmp4, vl);
            // inner: t*( u[i+3] + r*( u[i+2] + r*u[i+1] ) )
            vfloat32m1_t vtmp6 = __riscv_vfmul_vf_f32m1(vtmp5, t, vl);

            // sum inner parts
            vfloat32m1_t vsum_inner = __riscv_vfadd_vv_f32m1(vtmp6, vtmp3, vl);

            // outer: z[i] + r*y[i]
            vfloat32m1_t vtmp7 = __riscv_vfmacc_vf_f32m1(vz_i, r, vy_i, vl);
            // outer: u[i] + r*( z[i] + r*y[i] )
            vfloat32m1_t vtmp8 = __riscv_vfmacc_vf_f32m1(vu_i, r, vtmp7, vl);
            // final: add inner sum
            vfloat32m1_t vx = __riscv_vfadd_vv_f32m1(vtmp8, vsum_inner, vl);

            __riscv_vse32_v_f32m1(&x[i], vx, vl);
            i += vl;
        }
#else
        for (Index_type i = 0; i < LEN_1D - 6; ++i) {
            x[i] = u[i] + r*( z[i] + r*y[i] ) +
                          t*( u[i+3] + r*( u[i+2] + r*u[i+1] ) +
                             t*( u[i+6] + q*( u[i+5] + q*u[i+4] ) ) );
        }
#endif
        dummy(x, u, y, z, NULL, q);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

