            v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_tmp, vl);

            v_tmp = __riscv_vfmul_vv_f64m1(__riscv_vle64_v_f64m1((const double *)&px[i + offset * 7], vl), v_dm23, vl);
            v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_tmp, vl);

