real_t lcals_planckian(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        size_t vl;
        for (Index_type i = 0; i < LEN_1D; i += vl) {
            vl = __riscv_vsetvl_e32m1(LEN_1D - i);
            vfloat32m1_t vu = __riscv_vle32_v_f32m1(&u[i], vl);
            vfloat32m1_t vv = __riscv_vle32_v_f32m1(&v[i], vl);
            vfloat32m1_t vy = __riscv_vfdiv_vv_f32m1(vu, vv, vl);
            __riscv_vse32_v_f32m1(&y[i], vy, vl);

            // Compute expf(y[i]) - 1.0f using scalar loop since __riscv_vfexp is not available
            for (size_t j = 0; j < vl; j++) {
                float y_val = y[i + j];
                float exp_val = expf(y_val);
                w[i + j] = x[i + j] / (exp_val - 1.0f);
            }
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            y[i] = u[i] / v[i];
            w[i] = x[i] / ( expf(y[i]) - 1.0f );
        }
#endif
        dummy(y, w, u, v, x, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

