            vfloat32m1_t vec_xin = __riscv_vle32_v_f32m1(&xin[i-1], vl);
            vfloat32m1_t vec_sub = __riscv_vfsub_vv_f32m1(vec_y, vec_xin, vl);
            vfloat32m1_t vec_mul = __riscv_vfmul_vv_f32m1(vec_z, vec_sub, vl);
            __riscv_vse32_v_f32m1(&xout[i], vec_mul, vl);
