    gettimeofday(&func_args->t1, NULL);

    real_t dot_acc = 0.0;
    for (int nl = 0; nl < iterations; nl++) {
        real_t local = 0.0;
#if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t vec_sum = __riscv_vfmv_s_f_f32m1(0.0f, 1);
        Index_type i = 0;
        for (; i + 4 <= LEN_1D; i += vl) {
            vl = __riscv_vsetvl_e32m1(LEN_1D - i);
            vfloat32m1_t vec_a = __riscv_vle32_v_f32m1(&a[i], vl);
            vfloat32m1_t vec_b = __riscv_vle32_v_f32m1(&b[i], vl);
            vec_sum = __riscv_vfmacc_vv_f32m1(vec_sum, vec_a, vec_b, vl);
