        vfloat32m1_t vec_zero = __riscv_vfmv_v_f_f32m1(0.0f, 1);
        local = __riscv_vfmv_f_s_f32m1_f32(__riscv_vfredusum_vs_f32m1_f32m1(vec_sum, vec_zero, __riscv_vsetvl_e32m1(LEN_1D)));
